<?php require __DIR__.'/../../includes/db.php'; require __DIR__.'/../../includes/auth.php'; requireLogin(); $user=currentUser(); require_once __DIR__.'/../../includes/navigation.php'; ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thông báo</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="/assets/css/style.css"></head><body><div class="app-shell"><?php renderApplicationSidebar($user,'/views/thongbao/index.php'); ?><main class="main-panel"><header class="topbar"><div><h2>Thông báo</h2><p>Bấm vào thông báo để mở nội dung liên quan.</p></div></header><section class="card-panel"><div id="notificationList" class="list-group list-group-flush"></div></section></main></div><script src="/assets/js/app.js"></script><script>(()=>{const box=document.getElementById('notificationList');window.app.api('/api/thongbao.php').then(result=>{const items=result.data||[];box.innerHTML=items.map(item=>`<button class="list-group-item list-group-item-action ${item.DaDoc?'':'list-group-item-primary'} notify" data-id="${item.Id}" data-url="${item.DuongDan||''}"><div class="d-flex justify-content-between"><strong>${item.TieuDe}</strong><small>${String(item.NgayTao||'').replace(/(\d{4})-(\d{2})-(\d{2}).*/,'$3/$2/$1')}</small></div><div class="mt-1">${item.NoiDung}</div>${item.DuongDan?'<small class="text-primary d-block mt-2"><i class="bi bi-arrow-right-circle"></i> Mở nội dung liên quan</small>':''}</button>`).join('')||'<p class="text-muted mb-0">Chưa có thông báo.</p>'});document.addEventListener('click',async event=>{const notice=event.target.closest('.notify');if(!notice)return;await window.app.api('/api/thongbao.php?id='+notice.dataset.id,{method:'PUT'});notice.classList.remove('list-group-item-primary');if(notice.dataset.url)window.location.href=notice.dataset.url})})()</script></body></html>
